def svgpic(kind):
    small=kind=='small'; thin=kind=='thin'
    headline={'before':'Yesterday · a meal, not a drive','small':'Your trial · smaller, same recipe','thin':'Your trial · same size, thinner'}[kind]
    cupx=215; bottom=180; width=43 if small else 70; top=120 if small else 90
    shake=0 if small else (40 if thin else 65)
    body=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 350 245" font-family="system-ui" fill="#23343e"><text x="12" y="25" font-size="16" font-weight="700">{headline}</text><rect x="15" y="64" width="320" height="144" rx="20" fill="#f4f7f9"/><ellipse cx="100" cy="139" rx="60" ry="44" fill="white" stroke="#98afb9" stroke-width="3"/><text x="49" y="144" font-size="13">Meal finished</text><path d="M{cupx} {top} L{cupx+6} {bottom} H{cupx+width-6} L{cupx+width} {top} Z" fill="#fff4fa" stroke="#35434b" stroke-width="3"/><rect x="{cupx+8}" y="{bottom-shake}" width="{width-16}" height="{shake}" fill="#e885b1"/><path d="M{cupx+width*.55} {top+8} l12 -29 h15" fill="none" stroke="#35434b" stroke-width="4"/><text x="15" y="230" font-size="13">{('Less shake · same slow sips' if small else 'Same amount · quicker sips' if thin else 'A half-full shake leaves with the tray')}</text></svg>'''
    return dict(type='image',src='data:image/svg+xml;base64,'+base64.b64encode(body.encode()).decode(),alt=headline+'. Empty food plate beside '+('a smaller empty shake cup; slow sipping unchanged.' if small else 'a full-size shake cup; quicker sipping.' if thin else 'a half-full shake cup.'))
a['second']=dict(mood='thinking',line='Imagined afternoon: a parent buys a shake after lunch. The child takes a few slow sips, then goes back to chatting. Half leaves on the tray.',visual=svgpic('before'),choices=[{'label':'I put two samples on the counter.','next':'samples'}],note='Hypothetical behaviour, not reported HBS evidence. Do not assert an emotional motive as established.')
a['samples']=dict(mood='waiting',line='You can offer less shake with the same slow sips, or the full amount with quicker sips. Which afternoon sample do you put on the menu?',visual=dict(type='cards',items=[dict(title='Imagined sample rules',lines=['Smaller cup: same recipe, fewer slow sips.','Full cup: thinner recipe, more quick sips.','Both can be finished alongside the meal.']),dict(title='What you saw',lines=['Lunch was already eaten.','Only a few slow sips; then back to chatting.'])]),choices=[{'label':'I launch the smaller, thick shake.','small' if False else 'next':'small'},{'label':'I launch the full-size, thinner shake.','next':'thinner'}],note='Both plausible: preserve a few slow sips or preserve quantity. Rules disclose timing equivalence. No score or fixed preference winner: evidence supports a hypothesis, not guaranteed adoption.')
a['small']=dict(mood='thinking',consequence=True,line='You kept those slow sips and cut the amount. That fits a small treat after lunch. Now see whether families choose it again.',visual={**svgpic('small'),'caption':'Trial possibility: a smaller cup is finished. Repeat purchase is unknown.'},choices=[{'label':'Keep the afternoon plan separate.','next':'end'}])
a['thinner']=dict(mood='thinking',consequence=True,line='You kept the amount and changed the sipping. It can finish with the meal—but the child had already stopped after a few sips. More drink may not be the point.',visual={**svgpic('thin'),'caption':'Trial possibility: quicker sips. Whether the child drinks more is unknown.'},choices=[{'label':'Compare with fewer of the same slow sips.','next':'comparison'}])
a['comparison']=dict(mood='speaking',line='The smaller sample keeps the few slow sips you observed. It is a stronger idea to test here, not proof of what this family will buy.',visual=svgpic('small'),choices=[{'label':'Keep the afternoon plan separate.','next':'end'}])
a['end']=dict(mood='waiting',end=True,line='The commute needed something lasting. The meal may need a small treat. Same product; different progress. Watch the occasion before choosing the feature.',visual=dict(type='cards',items=[dict(title='Morning',lines=['Explore lasting through the drive.']),dict(title='Afternoon hypothesis',lines=['Explore a few slow sips after a meal.']),dict(title='Next evidence',lines=['Do they choose it again—and what do they choose instead?'])]))
